package com.projectdark.mobile;
import static org.junit.Assert.*;
import android.graphics.*;
import com.projectdark.mobile.world.*;
import org.junit.*;import org.junit.runner.RunWith;import org.json.*;
import org.robolectric.*;import org.robolectric.annotation.*;
import java.util.*;import java.io.*;import java.nio.charset.StandardCharsets;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class MageSourcesV235Test {
 final ScreenMagicV201Test h=new ScreenMagicV201Test();
 String mage(int n){return String.format(Locale.ROOT,"SK_마법사_%03d",n);}
 @Before public void setup(){h.setup();}
 JSONObject doc(String path)throws Exception{return new JSONObject(new String(PresentationAssetBytes.read(h.c,path),StandardCharsets.UTF_8));}
 RuntimeState.Monster add(RuntimeState s,String id,float x,float y)throws Exception{RuntimeState.Monster m=new RuntimeState.Monster(id,"V235",x,y,1000000,"B");((List<RuntimeState.Monster>)h.field(s,"monsters")).add(m);return m;}
 GameView actor(String id)throws Exception{
  GameView v=new GameView(h.c);v.layout(0,0,960,540);v.setSkillTestMode(false);RuntimeState s=h.field(v,"state");s.rpg().restoreProgression(99,0);assertTrue(s.rpg().restoreJobCode("MAGE"));s.rpg().restoreStats(100,100,100,100,100,0);s.rpg().restoreBaseResources(100000,100000);s.applyDerivedGrowth();s.player().hp=100000;s.player().mp=50000;((List<?>)h.field(s,"monsters")).clear();WorldRuntimeAdapter w=h.field(v,"worldAdapter");List<WorldMoveTargetController.TileCenter> tiles=new ArrayList<>(w.navigationTiles());tiles.sort(Comparator.comparingDouble(t->Math.hypot(t.x-WorldDef.PLAYER_SPAWN_X,t.y-WorldDef.PLAYER_SPAWN_Y)));boolean placed=false;
  for(WorldMoveTargetController.TileCenter t:tiles)if(w.canPlayerOccupy(t.x,t.y)&&w.canPlayerOccupy(t.x+32,t.y+16)&&w.hasLineOfSight(t.x,t.y,t.x+32,t.y+16)){s.player().x=t.x;s.player().y=t.y;placed=true;break;}assertTrue(placed);RuntimeState.Monster m=add(s,"mage-source-target",s.player().x+32,s.player().y+16);w.snapCameraToPlayer();((CombatController)h.field(v,"combat")).selectTarget(m);((CanonicalActorFacing)h.field(v,"playerFacing")).setLocomotion(CharacterRenderer.Direction.SE);SkillBook b=h.field(v,"skillBook");assertTrue(b.learn(id,100));assertTrue(b.assign(0,id));return v;
 }
 void tap(GameView v)throws Exception{RectF r=(RectF)h.call(v,"slotRect",new Class<?>[]{int.class},0);h.tap(v,r.centerX(),r.centerY());}
 void contact(GameView v)throws Exception{RuntimeCombatSession c=h.field(v,"combatSession");String id=h.field(v,"activeSkillVisualId");h.call(v,"tickSkillCombat",new Class<?>[]{float.class},c.effectiveCastSeconds(id)+.001f);}
 @Test public void all54GuideIconsOverrideBookAndQuickslotAndEveryDescriptionIsTheDisplayedText()throws Exception{
  SkillBook book=SkillBook.load(h.c);SkillIconCatalog icons=new SkillIconCatalog(h.c);SkillWindow window=new SkillWindow(book,icons);JSONArray rows=doc("skill-presentation/mage-v235/references.json").getJSONArray("rows");assertEquals(54,rows.length());Set<String> seen=new HashSet<>();Bitmap grid=Bitmap.createBitmap(720,540,Bitmap.Config.ARGB_8888);Canvas out=new Canvas(grid);out.drawColor(0xff303930);Paint paint=new Paint();
  for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String id=r.getString("id");assertTrue(seen.add(id));assertEquals("마법사",book.get(id).job);assertEquals(r.getString("description"),window.descriptionFor(book.get(id)));assertEquals(r.getString("description"),book.summary(id));assertEquals(r.getString("description"),book.get(id).effect);assertFalse(r.has("gold"));assertFalse(r.has("items"));
   Bitmap source=BitmapFactory.decodeStream(h.c.getAssets().open("skill-presentation/mage-v235/"+r.getString("iconAssetPath"))),actual=Bitmap.createBitmap(40,40,Bitmap.Config.ARGB_8888),expected=actual.copy(Bitmap.Config.ARGB_8888,true);paint.setFilterBitmap(true);new Canvas(expected).drawBitmap(source,null,new RectF(0,0,40,40),paint);assertTrue(icons.drawSquare(new Canvas(actual),id,new RectF(0,0,40,40)));assertTrue(id+" exact source icon on book",actual.sameAs(expected));out.drawBitmap(actual,i%9*80,i/9*85,null);
   actual.eraseColor(0);expected.eraseColor(0);Canvas ec=new Canvas(expected);Path clip=new Path();clip.addRoundRect(new RectF(0,0,40,40),3,3,Path.Direction.CW);ec.clipPath(clip);int inset=Math.max(1,Math.round(Math.min(source.getWidth(),source.getHeight())*.12f));paint.setFilterBitmap(false);ec.drawBitmap(source,new Rect(inset,inset,source.getWidth()-inset,source.getHeight()-inset),new RectF(0,0,40,40),paint);assertTrue(icons.drawQuickslot(new Canvas(actual),id,new RectF(0,0,40,40)));assertTrue(id+" exact source glyph on quickslot",actual.sameAs(expected));out.drawBitmap(actual,i%9*80+40,i/9*85,null);
  }RogueRepairV232Test.save(grid,"v235-all54-source-icons-both-surfaces");for(String n:new String[]{"054","055","057"})assertNull(book.sourceDescription("SK_마법사_"+n));
  GameView v=actor("SK_마법사_001");SkillWindow w=h.field(v,"skillWindow");w.open=true;w.showJob("마법사");for(String n:new String[]{"001","030","043","051"}){w.selectedId="SK_마법사_"+n;w.reveal(w.selectedId);h.capture(v,"v235-source-description-"+n);}
 }
 @Test public void allTwelveElementSourcesUseOnlyLowerThreeAndScreenRoutesReuseExactThirdTier()throws Exception{
  JSONObject skills=doc("skill-presentation/classic/manifest.json").getJSONObject("skills");ClassicSkillReference ref=new ClassicSkillReference(h.c);String[][] ids={{"001","013","026"},{"003","014","027"},{"004","015","028"},{"005","016","029"}};int[][] indices={{3,4,5},{9,10,11},{15,16,17},{21,22,23}};Bitmap grid=Bitmap.createBitmap(720,600,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(grid);c.drawColor(0xff303930);
  for(int e=0;e<4;e++)for(int tier=0;tier<3;tier++){String id="SK_마법사_"+ids[e][tier];JSONObject ch=skills.getJSONObject(id).getJSONObject("channels").getJSONObject("RECIPIENT_CONTACT");assertTrue(skills.getJSONObject(id).getString("article").endsWith("/221564"));JSONArray frames=ch.getJSONArray("sourceFrames");assertEquals(1,frames.length());assertEquals(indices[e][tier],frames.getJSONObject(0).getInt("index"));ClassicSkillReference.Channel channel=ref.channel(id,false);assertNotNull(channel);ref.draw(c,channel,.15f,100+tier*240,100+e*145);}
  for(int e=0;e<4;e++){String id=mage(30+e),single=mage(13+e);assertSame(ref.channel(single,false),ref.channel(id,false));assertEquals(SkillActionContract.Pattern.SCREEN,SkillActionContract.get(id).pattern);}RogueRepairV232Test.save(grid,"v235-twelve-lower-row-element-sources");
 }
 @Test public void fourScreenElementsUseNormalQuickslotsHitEveryVisibleLiveMonsterOnceAndEmitThirdTierPerRecipient()throws Exception{
  JSONArray trace=new JSONArray();for(int e=0;e<4;e++){h.setup();String id=mage(30+e);GameView v=actor(id);RuntimeState s=h.field(v,"state");RuntimeState.Monster first=s.monsters().get(0),second=add(s,"second",s.player().x-32,s.player().y+16),third=add(s,"third",s.player().x+96,s.player().y+48),outside=add(s,"outside",s.player().x+10000,s.player().y),dead=add(s,"dead",s.player().x+64,s.player().y+32);dead.alive=false;int mp=s.player().mp;tap(v);RuntimeCombatSession session=h.field(v,"combatSession");assertTrue(id,session.playerActionActive());assertEquals(id+" existing magic charges once at cast start",mp-session.effectiveMpCost(id),s.player().mp);assertEquals(first.maxHp,first.hp);contact(v);Set<String> expected=new HashSet<>(Arrays.asList(first.id,second.id,third.id));SkillVfxRenderer fx=h.field(v,"skillVfx");Set<String> actual=new HashSet<>();for(SkillVfxRenderer.Pulse p:fx.pulses)if(!p.caster&&p.id.equals(id)){assertEquals(id,"classic",p.sheet);assertTrue(actual.add(p.anchor));}assertEquals(id,expected,actual);Integer damage=null;for(RuntimeState.Monster m:new RuntimeState.Monster[]{first,second,third}){assertTrue(m.hp<m.maxHp);assertEquals(m.maxHp-m.hp,m.lastDamage);if(damage==null)damage=m.lastDamage;else assertEquals(damage.intValue(),m.lastDamage);}assertEquals(outside.maxHp,outside.hp);assertEquals(dead.maxHp,dead.hp);assertEquals(mp-session.effectiveMpCost(id),s.player().mp);trace.put(new JSONObject().put("id",id).put("recipients",new JSONArray(actual)).put("damagePerRecipient",damage).put("mpBefore",mp).put("mpAfter",s.player().mp));h.capture(v,"v235-screen-element-"+e);}
  File f=new File("build/reports/device-review/v235-screen-element-trace.json");f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){out.write(trace.toString(2).getBytes(StandardCharsets.UTF_8));}
 }
 @Test public void screenElementRecipientsAreRecheckedAtContactWithoutOffscreenEffects()throws Exception{
  GameView v=actor("SK_마법사_030");RuntimeState s=h.field(v,"state");RuntimeState.Monster m=s.monsters().get(0),remaining=add(s,"remaining",s.player().x-32,s.player().y+16);tap(v);m.x+=10000;contact(v);assertEquals(m.maxHp,m.hp);assertTrue(remaining.hp<remaining.maxHp);SkillVfxRenderer fx=h.field(v,"skillVfx");assertEquals(1,fx.pulses.stream().filter(p->!p.caster&&p.id.equals("SK_마법사_030")).count());assertTrue(fx.pulses.stream().noneMatch(p->p.anchor.equals(m.id)));
 }
 @Test public void allFourteenPromotionSpellsReachNormalQuickslotContactWithSourceEffectsAndCorrectAnchors()throws Exception{
  for(int n=39;n<=52;n++){h.setup();String id=mage(n);GameView v=actor(id);RuntimeState s=h.field(v,"state");RuntimeState.Monster m=s.monsters().get(0);tap(v);RuntimeCombatSession session=h.field(v,"combatSession");assertTrue(id,session.playerActionActive());contact(v);SkillVfxRenderer fx=h.field(v,"skillVfx");List<SkillVfxRenderer.Pulse> effects=new ArrayList<>();for(SkillVfxRenderer.Pulse p:fx.pulses)if(!p.caster&&p.id.equals(id))effects.add(p);assertEquals(id,1,effects.size());SkillVfxRenderer.Pulse p=effects.get(0);String expected=n==43?"meteor-source":n>=47&&n<=50?"curse-skull":"classic";assertEquals(id,expected,p.sheet);assertEquals(id,SkillActionContract.get(id).selfAnchored()&&SkillActionContract.get(id).pattern!=SkillActionContract.Pattern.SCREEN?"player":m.id,p.anchor);if(n==46){assertEquals(-1,CurseSkullFx.variant(id));assertFalse(fx.pulses.stream().anyMatch(x->x.sheet.equals("curse-skull")));}p.age=SkillFxAuditTest.sourcePeakAge(fx,p);h.capture(v,"v235-promotion-"+n);}
 }
}
